(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.015+t*0.32)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*8 + Math.cos(sy*0.02+t*0.35)*6;
  const w2y = Math.cos(sy*0.025+t*0.38)*8 + Math.sin(sx*0.022-t*0.42)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+1)*40, 0.13, 1.4, 0.8],
    [400+Math.cos(t*0.55+2)*70, 220+Math.sin(t*0.75+4)*50, 0.075, 2.1, 1.0]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.5)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.8+3.0)*w*0.5;
  }
  const act=aS/8, inh=iS/8, cross=cS/8;
  const bg1 = (Math.sin(fx*0.035+fy*0.022+t*0.8)+Math.sin(fx*0.028-fy*0.038+t*1.1)+Math.sin(fx*0.02+fy*0.05-t*0.6))/3;
  const bg2 = Math.sin((fx+fy)*0.1+t*2.2)*0.3+Math.sin((fx-fy)*0.08-t*1.8)*0.3;
  const bg3 = Math.sin(fx*0.08+fy*0.06+t*3.0)*0.15+Math.cos(fx*0.05-fy*0.09+t*2.5)*0.15;
  const bg = bg1+bg2+bg3;
  const dist = Math.sqrt((fx-cx)**2+(fy-cy)**2);
  const ang = Math.atan2(fy-cy, fx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3-t*1.5)+Math.sin(dist*0.035+ang*5-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.8))*0.3;
  const reaction = Math.tanh((act-inh*0.65+bg*0.25+spiral*0.4+cross*0.15)*2.0);
  const cell = Math.tanh((Math.sin(fx*0.12)*Math.sin(fy*0.12)+Math.sin((fx+fy)*0.08+t)*0.5+Math.sin(fx*0.06-fy*0.09+t*0.7)*0.3)*1.8)*0.3;
  const detail = Math.sin(fx*0.3+fy*0.2+t*4)*Math.sin(fx*0.2-fy*0.3-t*3)*0.15;
  const blend = reaction*0.6+cell*0.25+detail*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,85],[18,85,105],[30,135,120],[80,170,110],
    [170,190,70],[220,185,55],[230,140,65],[215,95,70],[180,60,75],
    [120,35,80],[60,20,70],[20,15,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0, pal.length-2), f=idx-i;
  const r=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(cross)*0.08;
  const edge=Math.abs(reaction)>0.65?1.2:(Math.abs(reaction)>0.45?1.05:1.0);
  const hs=Math.sin(ang*2+t*0.5)*8;
  return [
    Math.min(255,Math.max(0,(r+hs)*lum*edge))|0,
    Math.min(255,Math.max(0,(g-hs*0.5)*lum*edge))|0,
    Math.min(255,Math.max(0,(b+hs*0.3)*lum*edge))|0
  ];
}
